INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('S-2026-10-07-CL90-PREAUDIT','CL-90 preparatory live RegionBehavior graph scan and stableId coverage','verification','Central Lodge 21 Scenes','Foundry Playwright read-only independent inspection','active','work/foundry-playwright-harness/cl90-preaudit-readonly-v001.page.js; cl90-stableid-coverage-readonly-v001.page.js','2026-10-07','21 Scenes/202 Regions/115 behaviors/33 Items','Every Lodge behavior has one unique stable ID, all 115 enabled and nonempty. Counts 86 AmbientLights and 8 placed tokens across scenes. Three known transition scripts source-present. Source-mode classifier is heuristic, NOT evidence of 85 unsafe sources or final QA. No gameplay canary, CL-90 closure still pending.'),
('S-2026-10-07-CL51-LIGHT-INVENTORY','CL-51 existing ambient-light ownership and hidden state inventory','verification','Central Lodge 21 Scenes','Foundry no-write Scene AmbientLight enumeration','active','work/foundry-playwright-harness/cl51-lighting-inventory-readonly-v001.page.js','2026-10-07','86 existing AmbientLights, all hidden','There are 86 lights in 21 scenes: 86 hidden, 0 unhidden; F1 6 identified cicada/ward/threshold groups, F2 8 ritual/arrival groups; most remaining lights have no group shown in simple world.dicebox query. Only 14 passed a simple managed/campaign flag heuristic; other lights are not thereby proven foreign. No ledger time keys or E1 time flags observed; trigger policy remains unresolved. No lighting changed.');

INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-2026-10-07-CL90-PREAUDIT','campaign.central-lodge.qa',NULL,'CL-90 preaudit 115 existing RegionBehaviors no duplicates or missing IDs','A read-only broad scan found 21 canonical scenes, 202 Regions, 115 RegionBehaviors, 33 canonical Items, 86 AmbientLights and 8 placed Tokens. All 115 behavior sources nonempty, all enabled; separate stableId-coverage read found exactly 115 distinct nonempty behavior stable IDs and no collisions. The shared runtime kernel SHA and zero-revision ledger remained unchanged, and all three known travel scripts were present. This is a PRE-audit, not CL-90 final certification or player runtime test.','campaign','static','active','S-2026-10-07-CL90-PREAUDIT',NULL,'central lodge cl90 preaudit 115 unique behavior stableids'),
('F-2026-10-07-CL51-LIGHT-INVENTORY','campaign.central-lodge.lighting',NULL,'CL-51 86 hidden AmbientLights and undefined global night trigger','Foundry read-only inspection found 86 AmbientLights across 21 scenes, all hidden and none currently unhidden. F1 six lights are grouped as cicada, ward, threshold; F2 eight are grouped as ritual-core, ritual-periphery, arrival-manifestation. A simple world.dicebox managed/campaign flag check classified only 14, not proof that other lights are foreign. Global journal has no top-level time/day/night/light keys and E1 Scene has no time keys in the inspected flags. No GM choice of global night trigger has been recorded, so no blanket lighting activation or mutations permitted.','campaign','static','active','S-2026-10-07-CL51-LIGHT-INVENTORY',NULL,'central lodge lighting cl51 86 ambientlight hidden trigger choice pending');
INSERT INTO facts_fts(fact_id,title,statement,tags) SELECT fact_id,title,statement,tags FROM kb_facts WHERE fact_id IN ('F-2026-10-07-CL90-PREAUDIT','F-2026-10-07-CL51-LIGHT-INVENTORY')
AND NOT EXISTS(SELECT 1 FROM facts_fts f WHERE f.fact_id=kb_facts.fact_id);

INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-455','CL-51 lighting must preserve current hidden fixtures pending source ownership and trigger authority','Do not set any of the 86 existing AmbientLights to visible as a blanket action. Require explicit GM decision on campaign night trigger, exact per-light ownership/group reconciliation, and separate F1/F2 ritual-state trigger semantics; then PREVIEW, guarded APPLY, independent FINAL VERIFY. The 14 lights with simple managed/campaign flags do not authorize mutating unclassified lights.','Read-only audit found all 86 lights hidden; most lacked explicit flags in the initial lightweight ownership classifier. Infernal, underground and aboveground illumination have different state owners by campaign plan.','campaign','locked','Foreman','S-2026-10-07-CL51-LIGHT-INVENTORY',NULL);
INSERT INTO decisions_fts(decision_id,topic,decision,rationale) SELECT decision_id,topic,decision,rationale FROM kb_decisions WHERE decision_id='D-455'
AND NOT EXISTS(SELECT 1 FROM decisions_fts f WHERE f.decision_id=kb_decisions.decision_id);

